template.js:
const { view } = etude;
const slider = etude.$(".slider"), out = etude.$(".value");
const fmt = (v) => `${Number(v).toLocaleString()}${view.unit ? " " + view.unit : ""}`;
slider.value = String((Number(view.min) + Number(view.max)) / 2);
const show = () => (out.textContent = fmt(slider.value));
slider.addEventListener("input", show);
show();
etude.getAnswer(() => Number(slider.value));
etude.onResult(({ key, grade }) => {
  slider.disabled = true;
  out.style.color = grade.score >= 1 ? "var(--success)" : grade.score > 0 ? "var(--warning)" : "var(--danger)";
  const mark = document.createElement("div");
  mark.className = "truth";
  mark.dataset.label = "actual: " + fmt(key.answer);
  const pct = (key.answer - view.min) / (view.max - view.min);
  mark.style.left = `calc(${pct * 100}% )`;
  etude.$(".est").append(mark);
});

