const range = view.max - view.min;
const err = Math.abs(Number(answer) - key.answer) / range;
const t = key.tolerance;
const score = err <= t ? 1 : err >= 3 * t ? 0 : 1 - (err - t) / (2 * t);
return { score: Math.round(score * 100) / 100, details: { error: err } };

